public class InnerPrefetchScheduleRecurringRetrievalFactory(Action<Humidifier.MediaTailor.PrefetchScheduleTypes.RecurringRetrieval> factoryAction = null) : SubResourceFactory<Humidifier.MediaTailor.PrefetchScheduleTypes.RecurringRetrieval>
{

    internal InnerPrefetchScheduleTrafficShapingRetrievalWindowFactory TrafficShapingRetrievalWindowFactory { get; set; }

    internal InnerPrefetchScheduleTrafficShapingTpsConfigurationFactory TrafficShapingTpsConfigurationFactory { get; set; }

    protected override Humidifier.MediaTailor.PrefetchScheduleTypes.RecurringRetrieval Create()
    {
        var recurringRetrievalResult = CreateRecurringRetrieval();
        factoryAction?.Invoke(recurringRetrievalResult);

        return recurringRetrievalResult;
    }

    private Humidifier.MediaTailor.PrefetchScheduleTypes.RecurringRetrieval CreateRecurringRetrieval()
    {
        var recurringRetrievalResult = new Humidifier.MediaTailor.PrefetchScheduleTypes.RecurringRetrieval();

        return recurringRetrievalResult;
    }
    public override void CreateChildren(Humidifier.MediaTailor.PrefetchScheduleTypes.RecurringRetrieval result)
    {
        base.CreateChildren(result);

        result.TrafficShapingRetrievalWindow ??= TrafficShapingRetrievalWindowFactory?.Build();
        result.TrafficShapingTpsConfiguration ??= TrafficShapingTpsConfigurationFactory?.Build();
    }

} // End Of Class

